def posterior(sens, spec, base_rate):
    tp = sens * base_rate
    fp = (1 - spec) * (1 - base_rate)
    return tp / (tp + fp)              # P(disease | positive test)

for pi in [0.5, 0.05, 0.001]:
    print(f"base rate {pi:.3f}: precision {posterior(0.99, 0.99, pi):.3f}")

# Correct probabilities after undersampling negatives
def correct_prob(p, train_rate, true_rate):
    odds = p / (1 - p) * (true_rate / (1 - true_rate)) / (train_rate / (1 - train_rate))
    return odds / (1 + odds)

print(correct_prob(0.8, train_rate=0.5, true_rate=0.01))
